#Program 0
Please observe the naming conventions for f. 
- Function name: f
- Parameter: inputs

### Example Input/Output:
```
Input:
inputs = [(3, '(1+2)*3+3'), (2, '1*1*1+1*1*1'), (587, '1*(2*3*4)+5+((6+7*8))*(9)')]
Output:
outputs = [15, 4, 660]
```


```python
import re
import math

def f(inputs):
    result = []
    for n, s in inputs:
        stack = []
        for i, char in enumerate(s):
            # if char is (, add it to the stack
            # if char is ), calculate the expression inside the parentheses
            # if char is + or *, add it to the stack
            # if char is number, calculate the expression
            if char == '(':
                stack.append([char])
            elif char == ')':
                expr = stack.pop()
                value = calculate(expr)
                if len(stack) > 0:
                    stack[-1].append(value)
                else:
                    result.append(value)
            elif char.isdigit():
                if len(stack) > 0 and stack[-1][-1] == '*':
                    stack[-1][-1] = int(stack[-1][-1]) * int(char)
                else:
                    stack.append([int(char)])
            else:
                stack[-1].append(char)
    return result

def calculate(ex):
    values = [evaluate(stack) for stack in ex]
    value = values[0]
    for i in range(len(values) - 1):
        if values[i + 1] == '+':
            value += values[i + 2]
        elif values[i + 1] == '*':
            value *= values[i + 2]
    return value

def evaluate(stack):
    if len(stack) == 1:
        if isinstance(stack[0], str):
            stack = [eval(stack[0])]
        else:
            stack = [stack[0]]
    value = stack[-1]
    for i in range(len(stack) - 2, -1, -1):
        if stack[i] == '+':
            value += stack[i + 1]
        elif stack[i] == '*':
            value *= stack[i + 1]
    return value
```

